/** Base interface for objects that can be destroyed via a virtual member function.
 *
 *  @remarks This interface provides a destroy() member function that should be called
 *           instead of delete to properly clean up objects across DLL boundaries.
 */
class IDestroyable
{
protected:
    IDestroyable() = default;
    virtual ~IDestroyable() = default;

public:
    virtual void destroy() const noexcept = 0;
};

namespace detail
{

/** Creates a shared_ptr with a custom deleter that calls destroy().
 *
 *  @param p Raw pointer to an object of a type that implements IDestroyable.
 *  @returns A shared_ptr that will call destroy() when the reference count reaches zero.
 *
 *  @remarks This function creates a shared_ptr with a custom deleter that calls the destroy()
 *           member function instead of using delete. This is used for objects that manage their own
 *           lifetime through the destroy() member function rather than standard C++ destruction.
 *           If the input pointer is null, returns an empty shared_ptr.
 */
template <class T>
std::shared_ptr<T> shared_ptr_deleter_calls_destroy(T* p)
{
    return p ? std::shared_ptr<T>(p, [](IDestroyable* p) { p->destroy(); }) : std::shared_ptr<T>();
}

} // namespace detail

