/** Factory interface for creating metric instruments.
 *
 *  @remarks This interface provides member functions to create various types of metric instruments
 *           including counters, up/down counters, histograms, and observable instruments. These
 *           member functions are usually not invoked directly, instead use the namespace-scope function
 *           templates defined further in this file.
 */
class IMeter : public IDestroyable
{
protected:
    virtual ~IMeter() = default;

public:
    // The functions below are provided for ABI stability, it is recommended to use the corresponding member function
    // templates instead.S~
    virtual ICounter<std::uint64_t>* createCounter_uint64_t(carb::cpp::string_view name,
                                                            carb::cpp::string_view description,
                                                            carb::cpp::string_view unit) noexcept = 0;
    virtual ICounter<double>* createCounter_double(carb::cpp::string_view name,
                                                   carb::cpp::string_view description,
                                                   carb::cpp::string_view unit) noexcept = 0;
    virtual IUpDownCounter<std::int64_t>* createUpDownCounter_int64_t(carb::cpp::string_view name,
                                                                      carb::cpp::string_view description,
                                                                      carb::cpp::string_view unit) noexcept = 0;
    virtual IUpDownCounter<double>* createUpDownCounter_double(carb::cpp::string_view name,
                                                               carb::cpp::string_view description,
                                                               carb::cpp::string_view unit) noexcept = 0;
    virtual IHistogram<std::uint64_t>* createHistogram_uint64_t(carb::cpp::string_view name,
                                                                carb::cpp::string_view description,
                                                                carb::cpp::string_view unit) noexcept = 0;
    virtual IHistogram<double>* createHistogram_double(carb::cpp::string_view name,
                                                       carb::cpp::string_view description,
                                                       carb::cpp::string_view unit) noexcept = 0;
    virtual IGauge<std::int64_t>* createGauge_int64_t(carb::cpp::string_view name,
                                                      carb::cpp::string_view description,
                                                      carb::cpp::string_view unit) noexcept = 0;
    virtual IGauge<double>* createGauge_double(carb::cpp::string_view name,
                                               carb::cpp::string_view description,
                                               carb::cpp::string_view unit) noexcept = 0;
    virtual IObservableInstrument* createObservableCounter_int64_t(ObservableInstrumentCallback<std::int64_t> callback,
                                                                   void* context,
                                                                   carb::cpp::string_view name,
                                                                   carb::cpp::string_view description,
                                                                   carb::cpp::string_view unit) noexcept = 0;
    virtual IObservableInstrument* createObservableCounter_double(ObservableInstrumentCallback<double> callback,
                                                                  void* context,
                                                                  carb::cpp::string_view name,
                                                                  carb::cpp::string_view description,
                                                                  carb::cpp::string_view unit) noexcept = 0;
    virtual IObservableInstrument* createObservableUpDownCounter_int64_t(ObservableInstrumentCallback<std::int64_t> callback,
                                                                         void* context,
                                                                         carb::cpp::string_view name,
                                                                         carb::cpp::string_view description,
                                                                         carb::cpp::string_view unit) noexcept = 0;
    virtual IObservableInstrument* createObservableUpDownCounter_double(ObservableInstrumentCallback<double> callback,
                                                                        void* context,
                                                                        carb::cpp::string_view name,
                                                                        carb::cpp::string_view description,
                                                                        carb::cpp::string_view unit) noexcept = 0;
    virtual IObservableInstrument* createObservableGauge_int64_t(ObservableInstrumentCallback<std::int64_t> callback,
                                                                 void* context,
                                                                 carb::cpp::string_view name,
                                                                 carb::cpp::string_view description,
                                                                 carb::cpp::string_view unit) noexcept = 0;
    virtual IObservableInstrument* createObservableGauge_double(ObservableInstrumentCallback<double> callback,
                                                                void* context,
                                                                carb::cpp::string_view name,
                                                                carb::cpp::string_view description,
                                                                carb::cpp::string_view unit) noexcept = 0;

    /** Create a counter instrument with the specified ValueType.
     *
     *  @param[in] name The name of the counter instrument.
     *  @param[in] description A description of what the counter measures.
     *  @param[in] unit The unit of measurement (e.g., "bytes", "requests").
     *
     *  @returns A pointer to the created counter, or nullptr on failure.
     */
    template <class ValueType>
    ICounter<ValueType>* createCounter(carb::cpp::string_view name,
                                       carb::cpp::string_view description,
                                       carb::cpp::string_view unit = "") noexcept;

    /** Create an up/down counter instrument with the specified ValueType.
     *
     *  @param[in] name The name of the up/down counter instrument.
     *  @param[in] description A description of what the counter measures.
     *  @param[in] unit The unit of measurement (e.g., "bytes", "connections").
     *
     *  @returns A pointer to the created up/down counter, or nullptr on failure.
     */
    template <class ValueType>
    IUpDownCounter<ValueType>* createUpDownCounter(carb::cpp::string_view name,
                                                   carb::cpp::string_view description,
                                                   carb::cpp::string_view unit = "") noexcept;

    /** Create a histogram instrument with the specified ValueType.
     *
     *  @param[in] name The name of the histogram instrument.
     *  @param[in] description A description of what the histogram measures.
     *  @param[in] unit The unit of measurement (e.g., "ms", "bytes").
     *
     *  @returns A pointer to the created histogram, or nullptr on failure.
     */
    template <class ValueType>
    IHistogram<ValueType>* createHistogram(carb::cpp::string_view name,
                                           carb::cpp::string_view description,
                                           carb::cpp::string_view unit = "") noexcept;

    /** Create an observable counter instrument with the specified ValueType.
     *
     *  @param[in] callback The callback function to invoke for sampling the counter value.
     *  @param[in] context User-defined context passed to the callback.
     *  @param[in] name The name of the observable counter instrument.
     *  @param[in] description A description of what the counter measures.
     *  @param[in] unit The unit of measurement (e.g., "bytes", "requests").
     *
     *  @returns A pointer to the created observable instrument, or nullptr on failure.
     */
    template <class ValueType>
    IObservableInstrument* createObservableCounter(ObservableInstrumentCallback<ValueType> callback,
                                                   void* context,
                                                   carb::cpp::string_view name,
                                                   carb::cpp::string_view description,
                                                   carb::cpp::string_view unit = "") noexcept;

    /** Create an observable up/down counter instrument with the specified ValueType.
     *
     *  @param[in] callback The callback function to invoke for sampling the counter value.
     *  @param[in] context User-defined context passed to the callback.
     *  @param[in] name The name of the observable up/down counter instrument.
     *  @param[in] description A description of what the counter measures.
     *  @param[in] unit The unit of measurement (e.g., "bytes", "connections").
     *
     *  @returns A pointer to the created observable instrument, or nullptr on failure.
     */
    template <class ValueType>
    IObservableInstrument* createObservableUpDownCounter(ObservableInstrumentCallback<ValueType> callback,
                                                         void* context,
                                                         carb::cpp::string_view name,
                                                         carb::cpp::string_view description,
                                                         carb::cpp::string_view unit = "") noexcept;

    /** Create a gauge instrument with the specified ValueType.
     *
     *  @param[in] name The name of the gauge instrument.
     *  @param[in] description A description of what the gauge measures.
     *  @param[in] unit The unit of measurement (e.g., "celsius", "percent").
     *
     *  @returns A pointer to the created gauge, or nullptr on failure.
     */
    template <class ValueType>
    IGauge<ValueType>* createGauge(carb::cpp::string_view name,
                                   carb::cpp::string_view description,
                                   carb::cpp::string_view unit = "") noexcept;

    /** Create an observable gauge instrument with the specified ValueType.
     *
     *  @param[in] callback The callback function to invoke for sampling the gauge value.
     *  @param[in] context User-defined context passed to the callback.
     *  @param[in] name The name of the observable gauge instrument.
     *  @param[in] description A description of what the gauge measures.
     *  @param[in] unit The unit of measurement (e.g., "celsius", "percent").
     *
     *  @returns A pointer to the created observable instrument, or nullptr on failure.
     */
    template <class ValueType>
    IObservableInstrument* createObservableGauge(ObservableInstrumentCallback<ValueType> callback,
                                                 void* context,
                                                 carb::cpp::string_view name,
                                                 carb::cpp::string_view description,
                                                 carb::cpp::string_view unit = "") noexcept;
};

