/** Counter instrument for monotonically increasing values.
 *
 *  @remarks Counters are used to measure values that only increase over time,
 *           such as request counts, bytes processed, or errors encountered.
 *           Values added to a counter must be non-negative.
 */
template <class ValueType_>
class ICounter : public IDestroyable
{
protected:
    virtual ~ICounter() = default;

public:
    using ValueType = ValueType_;

    /** Add a value to the counter with attributes.
     *
     *  @param[in] value The value to add to the counter. Must be non-negative.
     *  @param[in] attributes Array of attributes to associate with this measurement.
     *  @param[in] attributeCount Number of attributes in the array.
     */
    virtual void addArr(ValueType value, const Attribute attributes[], std::size_t attributeCount) noexcept = 0;

    /** Add a value to the counter with variadic attributes.
     *
     *  @param[in] value The value to add to the counter. Must be non-negative.
     *  @param[in] a Variadic list of attributes to associate with this measurement.
     */
    template <class T, class... A>
    void add(T value, A&&... a) noexcept
    {
        const std::array<Attribute, sizeof...(A)> attrs = { Attribute(std::forward<A>(a))... };
        this->addArr(value, attrs.data(), sizeof...(A));
    }

    /** Add a value to the counter with initializer list of attributes.
     *
     *  @param[in] value The value to add to the counter. Must be non-negative.
     *  @param[in] attributes Initializer list of attributes to associate with this measurement.
     */
    template <class T>
    void add(T value, std::initializer_list<Attribute> attributes) noexcept
    {
        this->addArr(value, attributes.begin(), attributes.size());
    }
};

/** Up/down counter instrument for values that can increase or decrease.
 *
 *  @remarks Up/down counters are used to measure values that can go up or down,
 *           such as active connections, queue size, or memory usage.
 *           Values can be positive or negative.
 */
template <class ValueType_>
class IUpDownCounter : public IDestroyable
{
protected:
    virtual ~IUpDownCounter() = default;

public:
    using ValueType = ValueType_;

    /** Add a value to the up/down counter with attributes.
     *
     *  @param[in] value The value to add to the counter. Can be positive or negative.
     *  @param[in] attributes Array of attributes to associate with this measurement.
     *  @param[in] attributeCount Number of attributes in the array.
     */
    virtual void addArr(ValueType value, const Attribute attributes[], std::size_t attributeCount) noexcept = 0;

    /** Add a value to the up/down counter with variadic attributes.
     *
     *  @param[in] value The value to add to the counter. Can be positive or negative.
     *  @param[in] a Variadic list of attributes to associate with this measurement.
     */
    template <class T, class... A>
    void add(T value, A&&... a) noexcept
    {
        const std::array<Attribute, sizeof...(A)> attrs = { Attribute(std::forward<A>(a))... };
        this->addArr(value, attrs.data(), sizeof...(A));
    }

    /** Add a value to the up/down counter with initializer list of attributes.
     *
     *  @param[in] value The value to add to the counter. Can be positive or negative.
     *  @param[in] attributes Initializer list of attributes to associate with this measurement.
     */
    template <class T>
    void add(T value, std::initializer_list<Attribute> attributes) noexcept
    {
        this->addArr(value, attributes.begin(), attributes.size());
    }
};

/** Histogram instrument for recording distributions of values.
 *
 *  @remarks Histograms are used to measure the distribution of values,
 *           such as request latencies, response sizes, or processing times.
 *           They automatically create buckets to track value distributions.
 */
template <class ValueType_>
class IHistogram : public IDestroyable
{
protected:
    virtual ~IHistogram() = default;

public:
    using ValueType = ValueType_;

    /** Record a value in the histogram with attributes.
     *
     *  @param[in] value The value to record in the histogram.
     *  @param[in] attributes Array of attributes to associate with this measurement.
     *  @param[in] attributeCount Number of attributes in the array.
     */
    virtual void recordArr(ValueType value, const Attribute attributes[], std::size_t attributeCount) noexcept = 0;

    /** Record a value in the histogram with variadic attributes.
     *
     *  @param[in] value The value to record in the histogram.
     *  @param[in] a Variadic list of attributes to associate with this measurement.
     */
    template <class T, class... A>
    void record(T value, A&&... a) noexcept
    {
        const std::array<Attribute, sizeof...(A)> attrs = { Attribute(std::forward<A>(a))... };
        this->recordArr(value, attrs.data(), sizeof...(A));
    }

    /** Record a value in the histogram with initializer list of attributes.
     *
     *  @param[in] value The value to record in the histogram.
     *  @param[in] attributes Initializer list of attributes to associate with this measurement.
     */
    template <class T>
    void record(T value, std::initializer_list<Attribute> attributes) noexcept
    {
        this->recordArr(value, attributes.begin(), attributes.size());
    }
};

/** Gauge instrument for recording instantaneous values.
 *
 *  @remarks Gauges are used to measure values that can arbitrarily go up or down,
 *           such as current temperature, current memory usage, or current queue size.
 *           Unlike counters which accumulate values, gauges record the current value at the time of recording.
 */
template <class ValueType_>
class IGauge : public IDestroyable
{
protected:
    virtual ~IGauge() = default;

public:
    using ValueType = ValueType_;

    /** Record a value in the gauge with attributes.
     *
     *  @param[in] value The current value to record.
     *  @param[in] attributes Array of attributes to associate with this measurement.
     *  @param[in] attributeCount Number of attributes in the array.
     */
    virtual void recordArr(ValueType value, const Attribute attributes[], std::size_t attributeCount) noexcept = 0;

    /** Record a value in the gauge with variadic attributes.
     *
     *  @param[in] value The current value to record.
     *  @param[in] a Variadic list of attributes to associate with this measurement.
     */
    template <class T, class... A>
    void record(T value, A&&... a) noexcept
    {
        const std::array<Attribute, sizeof...(A)> attrs = { Attribute(std::forward<A>(a))... };
        this->recordArr(value, attrs.data(), sizeof...(A));
    }

    /** Record a value in the gauge with initializer list of attributes.
     *
     *  @param[in] value The current value to record.
     *  @param[in] attributes Initializer list of attributes to associate with this measurement.
     */
    template <class T>
    void record(T value, std::initializer_list<Attribute> attributes) noexcept
    {
        this->recordArr(value, attributes.begin(), attributes.size());
    }
};

/** Observable instrument that is sampled via callback.
 *
 *  @remarks Observable instruments are used for metrics that are sampled
 *           periodically rather than being updated directly by application code.
 *           Examples include CPU usage, memory consumption, or queue depth.
 */
class IObservableInstrument : public IDestroyable
{
protected:
    virtual ~IObservableInstrument() = default;
};

