/** Create an observable counter instrument with the specified ValueType.
 *
 *  @param[in] meter The meter to create the observable counter with.
 *  @param[in] callback The callback function to invoke for sampling the counter value.
 *  @param[in] context User-defined context passed to the callback.
 *  @param[in] name The name of the observable counter instrument.
 *  @param[in] description A description of what the observable counter measures.
 *  @param[in] unit The unit of measurement (e.g., "bytes", "requests").
 *
 *  @returns A shared pointer to the created observable counter, or nullptr on failure.
 *
 *  @remarks This is a convenience namespace-scope function template that is
 *           implemented in terms of the corresponding IMeter member function template.
 *           The @p meter argument is permitted to be null, in which case a null
 *           instrument pointer is returned.
 */
template <class ValueType>
std::shared_ptr<IObservableInstrument> createObservableCounter(const std::shared_ptr<IMeter>& meter,
                                                               ObservableInstrumentCallback<ValueType> callback,
                                                               void* context,
                                                               carb::cpp::string_view name,
                                                               carb::cpp::string_view description,
                                                               carb::cpp::string_view unit = "")
{
    if (!meter)
        return {};
    return detail::shared_ptr_deleter_calls_destroy(
        meter->createObservableCounter<ValueType>(callback, context, name, description, unit));
}

